using System;

// PROGRAM: Pembuktian Fleksibilitas Komposisi vs Pewarisan
public interface IReceiptPrinter
{
    void Print(string message);
}

public class ConsolePrinter : IReceiptPrinter
{
    public void Print(string message) => Console.WriteLine($"[PAPER PRINTER] {message}");
}

public class CloudEmailPrinter : IReceiptPrinter
{
    public void Print(string message) => Console.WriteLine($"[CLOUD EMAIL] Mengirim receipt via email: {message}");
}

// KOMPOSISI: Kasir 'MEMILIKI' alat cetak, bukan 'MERUPAKAN' alat cetak
public class CashierDesk
{
    private readonly IReceiptPrinter _printer;

    public CashierDesk(IReceiptPrinter printer)
    {
        _printer = printer;
    }

    public void Checkout(decimal amount)
    {
        Console.WriteLine($"Transaksi Rp {amount:N0} diterima.");
        _printer.Print($"Lunas Rp {amount:N0}");
    }
}

public class Program
{
    public static void Main()
    {
        // Mengganti perilaku output cukup dengan menukar komponen printer!
        var kasirToko = new CashierDesk(new ConsolePrinter());
        kasirToko.Checkout(150_000m);

        var kasirOnline = new CashierDesk(new CloudEmailPrinter());
        kasirOnline.Checkout(500_000m);
    }
}

