using System;

public interface IMessageSender
{
    string Send(string to, string body);
}

public class SmsSender : IMessageSender
{
    public string Send(string to, string body) => $"[SMS to {to}]: {body}";
}

public class AlertManager
{
    private readonly IMessageSender _sender;

    public AlertManager(IMessageSender sender)
    {
        _sender = sender ?? throw new ArgumentNullException(nameof(sender));
    }

    public string SendEmergencyAlert(string recipient, string alertCode)
    {
        string message = $"ALERT [{alertCode}]: Emergency detected!";
        return _sender.Send(recipient, message);
    }
}

public class Program
{
    public static void Main()
    {
        var alert = new AlertManager(new SmsSender());
        Console.WriteLine(alert.SendEmergencyAlert("+628123456", "E-99"));
    }
}
